import { useState } from "react";
import { Box, TextField, Button, Typography, Paper } from "@mui/material";
import axios from "axios";

const endpointMapping = {
  Notion: "notion",
  Airtable: "airtable",
  Hubspot: "hubspot",
};

export const DataForm = ({ integrationType, credentials }) => {
  const [loadedData, setLoadedData] = useState(null);
  const [loading, setLoading] = useState(false);
  const endpoint = endpointMapping[integrationType];

  const handleLoad = async () => {
    setLoading(true);
    try {
      const formData = new FormData();
      formData.append("credentials", JSON.stringify(credentials));

      const response = await axios.post(
        `http://localhost:8000/integrations/${endpoint}/load`,
        formData
      );

      const data = response.data;
      console.log("✅ Loaded data:", data);
      setLoadedData(data);
    } catch (e) {
      console.error("❌ Error loading data:", e);
      alert(e?.response?.data?.detail || "Failed to load data");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box
      display="flex"
      justifyContent="center"
      alignItems="center"
      flexDirection="column"
      width="100%"
      sx={{ p: 3 }}
    >
      <Typography variant="h6" gutterBottom>
        {integrationType} Integration
      </Typography>

      <Box display="flex" flexDirection="column" width="100%">
        {/* Load Button */}
        <Button
          onClick={handleLoad}
          sx={{ mt: 2 }}
          variant="contained"
          disabled={loading}
        >
          {loading ? "Loading..." : "Load Data"}
        </Button>

        {/* Clear Button */}
        <Button
          onClick={() => setLoadedData(null)}
          sx={{ mt: 1 }}
          variant="outlined"
        >
          Clear Data
        </Button>

        {/* Display Section */}
        {loadedData && (
          <Box sx={{ mt: 3, width: "100%", textAlign: "left" }}>
            <Typography variant="subtitle1" gutterBottom>
              Loaded Data:
            </Typography>

            {/* If array → render list of items */}
            {Array.isArray(loadedData) ? (
              loadedData.map((item, index) => (
                <Paper
                  key={index}
                  sx={{
                    p: 2,
                    mb: 2,
                    border: "1px solid #ccc",
                    borderRadius: 2,
                    backgroundColor: "#f9f9f9",
                  }}
                >
                  <Typography variant="subtitle2" fontWeight="bold">
                    {item.name || "Untitled"}
                  </Typography>
                  <Typography variant="body2">ID: {item.id}</Typography>
                  <Typography variant="body2">Type: {item.type}</Typography>
                  <Typography variant="body2">
                    Created: {item.creation_time || "N/A"}
                  </Typography>
                  <Typography variant="body2">
                    Updated: {item.last_modified_time || "N/A"}
                  </Typography>
                </Paper>
              ))
            ) : (
              // Fallback for single object or unexpected format
              <TextField
                label="Loaded Data (Raw)"
                value={JSON.stringify(loadedData, null, 2)}
                sx={{ mt: 2 }}
                InputLabelProps={{ shrink: true }}
                multiline
                minRows={6}
                fullWidth
                disabled
              />
            )}
          </Box>
        )}
      </Box>
    </Box>
  );
};
